def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_me, last_opp = history[-1]
    # Early phase: cooperate, but retaliate immediately when defected against
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'
    # Count cumulative cooperation
    coop = sum(1 for a, b in history if b == 'C')
    defco = n - coop
    if defco == 0:
        # Opponent never defected: cooperate, but exploit near the end
        if n >= 97:
            return 'D'
        return 'C'
    if coop == 0:
        return 'D'
    # Recent window analysis
    recent = history[-10:]
    rcoop = sum(1 for a, b in recent if b == 'C')
    rdef = 10 - rcoop
    # Opponent strongly cooperating recently: stay cooperative, but defect on final rounds
    if rcoop >= 9:
        if n >= 97:
            return 'D'
        return 'C'
    # Opponent strongly defecting recently: punish
    if rcoop <= 1:
        return 'D'
    # If opponent defected last round
    if last_opp == 'D':
        # Count consecutive defections by opponent
        streak = 0
        for m, o in reversed(history):
            if o == 'D':
                streak += 1
            else:
                break
        # Long defect streak: keep punishing
        if streak >= 3:
            return 'D'
        # If opponent is generally cooperative, retaliate once then forgive
        if coop > defco:
            # But if we also defected last round, try to break out of DD
            if last_me == 'D':
                return 'C' if streak <= 2 else 'D'
            return 'D'
        return 'D'
    # Opponent cooperated last round
    # If we defected last round and opponent cooperated, return to cooperation
    if last_me == 'D':
        return 'C'
    # Check for recent defection clusters
    if rdef >= 3:
        # Defect if opponent has been defecting somewhat recently
        if last_opp == 'C':
            # But if they just cooperated, give one more chance
            return 'C'
        return 'D'
    # If opponent has accumulated many defections relative to cooperation, be cautious
    if defco * 3 < n:
        # Opponent mostly cooperative but has defected: cooperate
        return 'C'
    if defco > coop * 2:
        # Opponent heavily defective: defect, with occasional probe
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    return 'C'
